 "content": "def transform(grid):
    """Fill one-cell horizontal gaps between same-colored isolated marks."""
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        colors = [v for v in row if v != row[0]]
        if not colors:
            continue
        ink = colors[0]
        bg = row[0]
        # The demos establish that the gap color is the color numerically
        # between the mark and background (1 and 3 -> 2).
        gap_color = (ink + bg) // 2
        for c in range(1, len(row) - 1):
            if row[c] == bg and row[c - 1] == ink and row[c + 1] == ink:
                out[r][c] = gap_color
    return out
